Vdel = [0,0,0]
buffer = []

def can_deliver(Vmsg, s):
    if Vmsg[s-1] != Vdel[s-1] + 1:
        return False
    for j in range(3):
        if j != s-1 and Vmsg[j] > Vdel[j]:
            return False
    return True

def try_deliver(Vmsg, s, name):
    if can_deliver(Vmsg, s):
        for j in range(3):
            Vdel[j] = max(Vdel[j], Vmsg[j])
        return name
    buffer.append((name, Vmsg, s))
    return None

try_deliver([1,1,0], 2, 'm2')
try_deliver([1,0,0], 1, 'm1')
for item in list(buffer):
    name, Vmsg, s = item
    if try_deliver(Vmsg, s, name) is not None:
        buffer.remove(item)
